<?php require 'config/db.php'; $drinks=$pdo->query("SELECT d.*,c.name category FROM drinks d LEFT JOIN categories c ON c.id=d.category_id WHERE d.is_active=1 ORDER BY c.name,d.name")->fetchAll(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Menu</title><link rel="stylesheet" href="css/style.css"></head><body><header><nav><a class="logo" href="index.php">🥤 DrinkShop</a><div><a href="menu.php">Menu</a> <a href="cart.php">Cart</a></div></nav></header><main><h1>Drink Menu</h1><div class="drink-grid"><?php foreach($drinks as $d):?><div class="drink-card"><?php if($d['image']):?><img class="drink-image" src="<?=e($d['image'])?>" alt="<?=e($d['name'])?>"><?php else:?><div class="drink-icon">🥤</div><?php endif;?><small><?=e($d['category'])?></small><h3><?=e($d['name'])?></h3><p><?=e($d['description'])?></p><strong>$<?=number_format($d['price'],2)?></strong><p>Stock: <?=e($d['stock'])?></p><?php if($d['stock']>0):?><form method="post" action="cart.php"><input type="hidden" name="drink_id" value="<?=$d['id']?>"><select name="size"><option>Small</option><option>Medium</option><option>Large</option></select><select name="sugar"><option>100% Sugar</option><option>75% Sugar</option><option>50% Sugar</option><option>25% Sugar</option><option>0% Sugar</option></select><select name="ice"><option>Normal Ice</option><option>Less Ice</option><option>No Ice</option></select><input type="number" name="qty" min="1" max="<?=$d['stock']?>" value="1"><button class="btn" name="add">Add to Cart</button></form><?php else:?><b>Out of stock</b><?php endif;?></div><?php endforeach;?></div></main></body></html>
